class EventTicket2{protected double balanceDue;EventTicket2(String id,double p){if(id==null||id.trim().length()<4||p<=0)throw new IllegalArgumentException();balanceDue=p;}void pay(double a){if(a>0)balanceDue=Math.max(0,balanceDue-a);}double getBalanceDue(){return balanceDue;}void printTicket(){System.out.println("Standard Event Ticket | Balance Due: "+balanceDue);}}
class WorkshopTicket2 extends EventTicket2{protected String track;WorkshopTicket2(String i,double p,String t){super(i,p);track=t;}void printTicket(){System.out.println("Workshop Ticket | Track: "+track+" | Balance Due: "+balanceDue);}}
class PremiumWorkshopTicket extends WorkshopTicket2{double kitFee;PremiumWorkshopTicket(String i,double p,String t,double f){super(i,p,t);kitFee=f;}void printTicket(){System.out.println("Premium Workshop Ticket | Track: "+track+" | Kit Fee: "+kitFee+" | Balance Due: "+balanceDue);}}
class HackathonTicket extends EventTicket2{String teamName;HackathonTicket(String i,double p,String t){super(i,p);teamName=t;}void printTicket(){System.out.println("Hackathon Ticket | Team: "+teamName+" | Balance Due: "+balanceDue);}}
public class Problem2{static String classifyGeneration(EventTicket2 t){if(t instanceof PremiumWorkshopTicket)return "multilevel descendant (3 generations deep)";if(t instanceof HackathonTicket)return "Hierarchical sibling (independent branch)";return t instanceof WorkshopTicket2?"Workshop descendant":"Standard";}static double getTotalBalanceDue(EventTicket2[] a){double s=0;for(EventTicket2 t:a)s+=t.getBalanceDue();return s;}public static void main(String[]x){EventTicket2[]a={new EventTicket2("STU1",500),new WorkshopTicket2("STU2",1200,"AI/ML"),new PremiumWorkshopTicket("STU3",2000,"Cloud Native",300),new HackathonTicket("STU4",800,"Byte Force")};for(EventTicket2 t:a)t.printTicket();System.out.println(getTotalBalanceDue(a));}}
